entries[35230] = { ["name"] = "Darnarians Rolle der Teleportation", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Teleportiert den Zaubernden von der Insel von Quel'Danas nach Shattrath. (20 Sek. Abklingzeit)" }
