entries[35233] = { ["name"] = "Spektrografische Multiphasenbrille", ["text"] = "QuestgegenstandKopf\nAnlegen: Ermöglicht es dem Träger, auf den Geisterfeldern von Nagrand Multiphasenstörungen zu entdecken.\nBenutzen: Nehmt eine Multiphasenmessung an einer dunklen Multiphasenstörung im Umkreis von 20 Metern vor. (10 Sek. Abklingzeit)" }
