entries[35237] = { ["name"] = "Krabbenkugel", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Verwandelt Euch 3 Min. lang in eine unschuldige Krabbe. Kann nur am Zoramstrand im Eschental benutzt werden. Nur die neuen Schattenhammerkultisten und ihre Verbündeten werden davon getäuscht werden. Durch Plündern, feindselige Aktionen oder das Wirken von Stärkungszaubern wird die Verkleidung unwirksam." }
