entries[35273] = { ["name"] = "Abhandlung über hochentwickelte Verhüttung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung von gehärtetem Khorium.\nErmöglicht dem Minenarbeiter, Khoriumbarren und gehärtete Adamantitbarren zu einem gehärteten Khoriumbarren zu verhütten. Das Verhütten von gehärtetem Khorium erfordert eine Schmiede.\nBenötigt Bergbau der Scherbenwelt (75)\nVerkaufspreis:\nGehärtetes Khorium\nHandwerksmaterial\nVerkaufspreis:\nBenötigt Khoriumbarren (3), Gehärteter Adamantitbarren" }
