entries[35498] = { ["name"] = "Formel: Waffe - Todeskälte", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Todeskälte' durchführt.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass Schadenszauber und Nahkampftreffer gelegentlich zusätzlich Frostschaden verursachen und das Ziel verlangsamen. Der Verlangsamungseffekt ist bei Zielen der Stufe 50 oder höher unwirksam. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Verzauberkunst der Scherbenwelt (50)\nVerkaufspreis:" }
entries[35500] = { ["name"] = "Formel: Brust - Ausweichen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Ausweichen' bei Brustrüstung durchführt.\nEine Brustrüstung dauerhaft verzaubern, sodass das Ausweichen um 3 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst der Scherbenwelt (60)\nBenötigt Offensive der Zerschmetterten Sonne\n- Wohlwollend\nVerkaufspreis:" }
